import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";import{t as i}from"./chunks/assets.DdS4fYtI.js";var a=JSON.parse(`{"title":"Marg — agents that finish the job","description":"","frontmatter":{"layout":"home","title":"Marg — agents that finish the job","hero":{"name":"Marg","text":"Agents that finish the job.","tagline":"The open-source Agent Development Kit for conversational agents that complete a transaction. The runtime owns the moments that must be right; the model owns the conversation. TypeScript, MCP, any model.","actions":[{"theme":"brand","text":"Get started","link":"/get-started/"},{"theme":"alt","text":"Try the playground","link":"https://marg-playground.onrender.com"},{"theme":"alt","text":"GitHub","link":"https://github.com/marg-adk/marg"}]},"features":[{"title":"The runtime owns the moments that must be right","details":"Forms, pickers, option chips, the confirmation summary and the create gate are drawn and read by the runtime, in code, by the whole message. A model that skips a question, invents a value, or reads \\"yes but change the title\\" as a yes cannot do so here.","link":"/build/pattern","linkText":"The pattern"},{"title":"Typed decisions, not prose","details":"Which domain, is this a yes, which option, is it safe to write — asked as choice / noul / score questions and answered by rules first, a decision model second, an LLM with logprobs last, with calibrated confidence.","link":"/components/decisions","linkText":"Verdict"},{"title":"Evals as the ratchet, offline","details":"Scripted conversations against a writes-off gateway with deterministic checks, a mock model that plays the model's part, flake classification, a gate that runs in CI with no key and no network.","link":"/build/evals","linkText":"Evals"},{"title":"A production spine","details":"Identity that fails closed, owner checks, rate limits, usage caps, pass-through metering, OpenTelemetry in the GenAI conventions, dashboards and alerts as code, graceful deploys, a widget people use on a phone.","link":"/run/production-checklist","linkText":"Going to production"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),o={name:`index.md`};function s(n,a,o,s,c,l){return e(),r(`div`,null,[...a[0]||=[t(`<div class="marg-gif"><img src="`+i+`" alt="The playground: a ticket typed in one sentence, a customer picker, category chips, a details card the runtime draws and reads, priority chips, a summary with provenance, the create."></div><h2 id="two-minutes-to-a-running-agent" tabindex="-1">Two minutes to a running agent <a class="header-anchor" href="#two-minutes-to-a-running-agent" aria-label="Permalink to “Two minutes to a running agent”">​</a></h2><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-4" id="tab-5" checked><label data-title="npm" for="tab-5">npm</label><input type="radio" name="group-4" id="tab-6"><label data-title="the repository" for="tab-6">the repository</label></div><div class="blocks"><div class="language-bash active"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-marg-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">        # http://localhost:8787 — the scripted mock model, no key</span></span></code></pre></div><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/marg-adk/marg.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marg</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">        # http://localhost:8787</span></span></code></pre></div></div></div><p>Open the playground and type <strong>&quot;ticket for Northwind: login fails on mobile&quot;</strong>. A customer picker, category chips, a details card the runtime draws and reads, priority chips, a summary with <em>Change something</em>, the create. Switch to a real model by editing one line in <code>.env</code> (<code>LLM_CHAIN=anthropic</code>, <code>LLM_CHAIN=openai,anthropic</code>, <code>LLM_CHAIN=ollama</code>); nothing else changes.</p><h2 id="measured-in-the-field" tabindex="-1">Measured in the field <a class="header-anchor" href="#measured-in-the-field" aria-label="Permalink to “Measured in the field”">​</a></h2><p>The numbers that justified the design, from the production agent Marg was extracted from.</p><div class="marg-numbers"><table tabindex="0"><thead><tr><th>Observation</th><th>Result</th></tr></thead><tbody><tr><td>Questions a model-led prompt skipped, despite the rule</td><td>25 to 50 percent of turns</td></tr><tr><td>List items a model attested that the user never said</td><td>1 chat in 64</td></tr><tr><td>Typed replies a leading-word reader mis-read as a bare yes or no, blind corpus of 521</td><td>235</td></tr><tr><td>The same corpus, read by the whole content</td><td>0</td></tr><tr><td><code>ui</code> blocks malformed around the fence in production traffic</td><td>about 1 in 40, all parsed</td></tr></tbody></table></div><p><a href="/marg/community/posts/the-model-must-never-read-yes">The model must never read &quot;yes&quot;</a> tells the story behind the third and fourth rows.</p><h2 id="is-marg-for-you" tabindex="-1">Is Marg for you? <a class="header-anchor" href="#is-marg-for-you" aria-label="Permalink to “Is Marg for you?”">​</a></h2><p><strong>Use Marg when</strong> your agent must complete a transaction, not only answer; when the result is published under a real user&#39;s name; when several specialist agents sit behind one entry point; when you need to prove behaviour before and after every change without burning model credits; when you are going to run it yourself.</p><p><strong>Look elsewhere when</strong> you want a general library for arbitrary agent graphs, your bot only answers and never writes, you want a hosted platform, or your stack must be Python end to end. <a href="/marg/get-started/compare">Marg and other frameworks</a> says where the line is.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to “Frequently asked questions”">​</a></h2><details class="details custom-block"><summary>Which models can I use?</summary><p>Anthropic, and any OpenAI-compatible endpoint: OpenAI, Ollama, vLLM, Fireworks, Together, DeepSeek, Gemini through its OpenAI-compatible API. A chain of endpoints with failover and a circuit breaker is one environment line, <code>LLM_CHAIN=openai,anthropic</code>. The scripted mock model runs everything with no key. <a href="/marg/run/environment">Environment</a>.</p></details><details class="details custom-block"><summary>What makes Marg different from an agent framework?</summary><p>Marg is opinionated about one job shape, <em>collect → validate → confirm → write</em>, and puts the costly moments in the runtime instead of the prompt. The reader that reads &quot;yes&quot; by the whole message, the three-fold write gate, and the offline eval gate exist because their absence cost something in production. <a href="/marg/build/pattern">The pattern</a> explains each rule and the failure it answers.</p></details><details class="details custom-block"><summary>How do I connect my backend?</summary><p>Through an MCP tool server, in any language: reads, and the triad <code>validate_*</code>, <code>preview_*</code>, <code>create_*</code>. The example domain&#39;s server is the reference; probe the real backend before trusting its documentation. <a href="/marg/build/new-domain">A new domain</a>.</p></details><details class="details custom-block"><summary>How do I prove it still works after a change?</summary><p>Run the gate: unit tests, the OpenTelemetry check, the scaffold check, the real-write e2e, and the example suite against a writes-off gateway, all on the mock model. Every red is classified before it is fixed. <a href="/marg/build/evals">Evals</a>.</p></details><details class="details custom-block"><summary>How do I deploy it?</summary><p>One non-root image, Compose profiles for stores, observability, decisions and the TLS edge, and a Render blueprint for a demo. <a href="/marg/run/deploy">Deploy</a>, then the <a href="/marg/run/production-checklist">production checklist</a>.</p></details>`,17)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};